class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        # approach 1: brute-force
        # accumulate multiple non-decreasing subarrays that follow the order of array
        # return the length of the longest subarray

        # approach 2: dynamic programming
        n = len(nums)
        dp = [1] * n
        for i in range(n):

            for j in range(i):
                if nums[j] < nums[i]:
                    dp[i] = max(dp[i], dp[j] + 1)
            # ^ we can do binary search instead of this loop tho

        return max(dp)
